CREATE TABLE IF NOT EXISTS "channles" (
	"id" INTEGER NOT NULL UNIQUE,
	"username" VARCHAR(255) NOT NULL,
	"last_message_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "subscribers" (
	"id" INTEGER NOT NULL UNIQUE,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "themes" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"last_offset" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "subscription" (
	"subscriber_id" INTEGER NOT NULL UNIQUE,
	"theme_id" INTEGER NOT NULL UNIQUE,
	PRIMARY KEY("subscriber_id", "theme_id")
);

ALTER TABLE "themes"
ADD FOREIGN KEY("id") REFERENCES "subscription"("theme_id")
ON UPDATE RESTRICT ON DELETE CASCADE;
ALTER TABLE "subscribers"
ADD FOREIGN KEY("id") REFERENCES "subscription"("subscriber_id")
ON UPDATE RESTRICT ON DELETE CASCADE;